package app.xiaohe.tests;

import android.app.*;
import android.content.Intent;
import android.webkit.WebView;
import app.xiaohe.assistant.*;
import org.json.*;
import java.lang.reflect.Field;

/** Independent real-IME acceptance; keyboard overlap must fail instead of being hidden by navigation setup. */
public final class ChatEditKeyboardSmoke {
  public static JSONObject run(Instrumentation test)throws Exception{
    Activity activity=test.startActivitySync(new Intent(test.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));WebView web=VoiceSupport.web(activity);Field member=MainActivity.class.getDeclaredField("store");member.setAccessible(true);Object previous=member.get(activity);JSONObject oldStorage=null;
    try{ChatEditSupport.wait(test,web,"typeof state!=='undefined'&&state.draftRestored&&pendingCalls.size===0&&typeof chatEdit!=='undefined'","Attached-card keyboard initial bootstrap completed");oldStorage=new JSONObject(ChatEditSupport.js(test,web,"(()=>{const keys=['xiaohe-draft','xiaohe-draft-files','xiaohe-draft-anchor','xiaohe-draft-edit-context'],out={};for(const key of keys)out[key]=localStorage.getItem(key);return out;})()"));try(ChatEditSupport.Fixture fixture=new ChatEditSupport.Fixture(test)){Store db=fixture.scope.db;member.set(activity,db);JSONObject row=ChatEditSupport.memory(db,"合成附卡键盘条目","这段资料保持原样，键盘检查不发送。","note","note"),voice=ChatEditNativeSmoke.voice(db,ChatEditNativeSmoke.CAPTURED);String draft="已有的合成草稿\n第二行继续保留\n第三行可在输入框中滚动";ChatEditSupport.js(test,web,"(()=>{clearDraft();state.draftRestored=true;loadData("+db.bootstrap()+");document.getElementById('message-input').value="+JSONObject.quote(draft)+";state.pending.set("+JSONObject.quote(voice.getString("id"))+","+voice+");state.files.set("+JSONObject.quote(voice.getString("id"))+","+voice+");state.draftAnchor={capturedAt:"+voice.getLong("capturedAt")+",capturedZone:'Asia/Shanghai',anchorFileId:"+JSONObject.quote(voice.getString("id"))+"};renderPending();saveDraft();return true;})()");ChatEditUiSmoke.detail(test,web,row.getString("id"));ChatEditSupport.tap(test,web,"#detail-body button[data-edit-memory]");ChatEditSupport.wait(test,web,"state.view==='chat'&&chatEdit.hasContext()&&pendingCalls.size===0","Synthetic memory is attached before the real keyboard test");JSONObject geometry=ChatEditSupport.showKeyboard(test,activity,web);ChatEditSupport.proof(test,"keyboard-visible-geometry",geometry);ChatEditSupport.screenshot(test,web,"attached-keyboard-visible");double safe=geometry.getJSONObject("native").getDouble("safeBottom");ChatEditSupport.check(geometry.getDouble("inputScreenBottom")<=safe+4&&geometry.getDouble("sendScreenBottom")<=safe+4,"Attached-card input and Send must be above the actual native IME: "+geometry);ChatEditSupport.check("true".equals(ChatEditSupport.js(test,web,"document.getElementById('message-input').value==="+JSONObject.quote(draft))),"Real IME preserves the multiline draft with an attached memory and pending voice");ChatEditSupport.hideKeyboard(test,web);return new JSONObject().put("realNativeImeShown",true).put("attachedMemoryAndPendingVoice",true).put("inputAndSendAboveIme",true).put("measurements",geometry).put("aiRequests",0);}}
    finally{try{ChatEditSupport.hideKeyboard(test,web);}catch(Exception ignored){}member.set(activity,previous);try{if(oldStorage!=null)ChatEditSupport.js(test,web,"(()=>{const old="+oldStorage+";for(const key of Object.keys(old)){if(old[key]===null)localStorage.removeItem(key);else localStorage.setItem(key,old[key]);}return true;})()");}finally{test.runOnMainSync(activity::finish);}}
  }
}
